#pragma once
inline void RunStreamerLifetimeTests(Suite& suite){
    for(unsigned variant=0;variant<3;++variant)suite.Test(std::string("R7 T08 two-worker destroy-before-credit actual heap ")+(variant==0?"no-cache":variant==1?"optional-cache":"cached"),[=]{
        Context context("r7-heap-"+std::to_string(variant));auto config=Config();config.maxDepth=0;config.maxPageGaussians=8192;std::vector<FSplatGaussian> gaussians;gaussians.reserve(16384);for(unsigned i=0;i<16384;++i)gaussians.push_back(Gaussian(i));auto manifest=Build(context,gaussians,config);Require(manifest.pages.size()==2,"two real page fixture shape");
        auto& probe=SplatHeapProbe::state;probe.Reset();probe.encodedBytes=manifest.pages[0].byteSize;probe.decodedBytes=8192*sizeof(FSplatGaussian);
        Require(manifest.pages[1].byteSize==probe.encodedBytes&&manifest.pages[0].decodedByteSize==probe.decodedBytes,"real encoded/decoded allocator size identity");
        FSplatStreamingConfig streaming;streaming.maxConcurrentReads=2;streaming.cpuCacheBytes=probe.encodedBytes+probe.decodedBytes+4096+(variant?probe.encodedBytes:0);FSplatPageStreamer streamer;SplatHeapProbe::Cleanup cleanup;probe.streamer=&streamer;std::string error;Require(streamer.Open(manifest,(context.dir/"scene").string(),streaming,error),error);
        streamer.SetFaultInjector([](unsigned page,unsigned){SplatHeapProbe::workerPage=page;SplatHeapProbe::workerArmed=SplatHeapProbe::state.armed.load();return FSplatPageReadFault{};});probe.active=true;
        if(variant==2){streamer.Request({{0,1,1}});auto primed=Wait(streamer);Require(primed[0].error.empty(),"cache prime failed");Release(streamer,primed[0]);Require(streamer.GetMemoryStats().encodedCacheBytes==probe.encodedBytes&&probe.live>=probe.encodedBytes&&probe.live<=probe.encodedBytes+64,"cache prime physical lifetime not observed");}
        probe.armed=true;streamer.Request({{0,100,1}});auto deadline=std::chrono::steady_clock::now()+std::chrono::seconds(5);while(!probe.decodeEntered&&std::chrono::steady_clock::now()<deadline)std::this_thread::sleep_for(std::chrono::milliseconds(1));Require(probe.decodeEntered,"actual decode allocation barrier not reached");
        auto chargedDuringDecode=streamer.GetMemoryStats().totalReservedBytes;Require(probe.live>0&&probe.live<=chargedDuringDecode&&chargedDuringDecode<=streaming.cpuCacheBytes,"actual decode payload not charged before cancellation");
        streamer.UpdateRequests({{1,200,1}});std::this_thread::sleep_for(std::chrono::milliseconds(30));Require(probe.replacementAllocations==0,"second payload admitted while old working set still charged");probe.releaseDecode=true;
        deadline=std::chrono::steady_clock::now()+std::chrono::seconds(5);while(!probe.deleteEntered&&std::chrono::steady_clock::now()<deadline)std::this_thread::sleep_for(std::chrono::milliseconds(1));Require(probe.deleteEntered&&probe.deleting,"successful obsolete physical destructor barrier not reached");
        // The destructor remains physically blocked while the other real worker can
        // attempt admission. Fixed code keeps that mutex/credit until destruction.
        deadline=std::chrono::steady_clock::now()+std::chrono::milliseconds(1500);while(std::chrono::steady_clock::now()<deadline&&!(probe.uncharged&&probe.peak>streaming.cpuCacheBytes))std::this_thread::sleep_for(std::chrono::milliseconds(1));probe.releaseDelete=true;
        auto replacement=Wait(streamer);Require(replacement[0].pageId==1&&replacement[0].error.empty(),"replacement real page completion failed");Release(streamer,replacement[0]);Require(streamer.DrainReady().empty(),"obsolete decoded result escaped wanted cancellation");
        auto stats=streamer.GetStats();auto memory=streamer.GetMemoryStats();streamer.Shutdown();probe.active=false;auto final=streamer.GetMemoryStats();
        std::ofstream evidence(context.dir/"allocation-evidence.json");evidence<<"{\"workers\":2,\"variant\":"<<variant<<",\"budget\":"<<streaming.cpuCacheBytes<<",\"encodedBytes\":"<<probe.encodedBytes<<",\"decodedBytes\":"<<probe.decodedBytes<<",\"chargedDuringDecode\":"<<chargedDuringDecode<<",\"physicalPeak\":"<<probe.peak<<",\"reservationPeak\":"<<memory.peakReservedBytes<<",\"observedPhysicalDuringEarlyAdmission\":"<<probe.observedLive<<",\"observedChargeDuringEarlyAdmission\":"<<probe.observedCharge<<",\"earlyAdmission\":"<<(probe.earlyAdmission?"true":"false")<<",\"unchargedPayload\":"<<(probe.uncharged?"true":"false")<<",\"oldEncodedCopies\":"<<probe.oldEncodedCopies<<",\"cacheHits\":"<<stats.cacheHits<<",\"cancelled\":"<<stats.cancelled<<",\"finalPhysical\":"<<probe.live<<",\"finalReserved\":"<<final.totalReservedBytes<<"}\n";evidence.close();Require(bool(evidence),"lifetime evidence artifact write failed");
        Require(!probe.timeout,"allocator observation capacity/deadline failed");Require(!probe.earlyAdmission&&!probe.uncharged&&probe.peak<=streaming.cpuCacheBytes,"replacement allocation reused reservation before physical obsolete payload destruction");Require(probe.live==0&&final.totalReservedBytes==0,"physical payload/reservation ownership failed shutdown closure");Require(stats.cancelled>=1&&probe.replacementAllocations>0,"concurrent replacement did not actually progress");if(variant==1)Require(probe.oldEncodedCopies==2,"optional encoded cache copy not physically exercised");if(variant==2)Require(stats.cacheHits>=1,"cached obsolete completion path not exercised");
    });
}
